code.java:
class Solution {
    public int minPairSum(int[] nums){
        Arrays.sort(nums);
        int answer=0;
        for(int left=0,right=nums.length-1;left<right;left++,right--)answer=Math.max(answer,nums[left]+nums[right]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minPairSum(nums:IntArray):Int{
        nums.sort();
        var answer=0;
        var left=0;
        var right=nums.lastIndex;
        while(left<right)answer=maxOf(answer,nums[left++]+nums[right--]);
        return answer
    }
}

